typedef float rational_t;

extern "C" float __fsqrt(float);

class vector3d
{
public:
  rational_t x, y, z;

  inline vector3d() {}
  inline vector3d& operator *= (rational_t d)
  {
    x *= d;
    y *= d;
    z *= d;
    return *this;
  }
  inline rational_t length() const
  {
    return (rational_t)__fsqrt(x*x + y*y + z*z);
  }
};

class vector4d
{
public:
  rational_t x, y, z, w;
};

class matrix4x4
{
public:
  vector4d x __attribute__((aligned(16)));
  vector4d y;
  vector4d z;
  vector4d w;
};

class po
{
private:
  matrix4x4 m;

public:
  inline rational_t get_scale() const
  {
    return ((const vector3d&)m).length();
  }

  vector3d non_affine_inverse_scaled_xform(const vector3d& v) const;
};

vector3d po::non_affine_inverse_scaled_xform( const vector3d & v ) const
{
  vector3d result;
  result.x = m.x.x * v.x + m.x.y * v.y + m.x.z * v.z;
  result.y = m.y.x * v.x + m.y.y * v.y + m.y.z * v.z;
  result.z = m.z.x * v.x + m.z.y * v.y + m.z.z * v.z;

  rational_t s = get_scale();
  if ( s<0.999f || s>1.001f )
    result *= 1.0f / (s*s);

  return result;
}
